def field_catalog()->list[dict]:
    out=[]
    for key,title,count in CATEGORIES:
        fields=BASE_FIELDS.get(key,[])
        # Keep the user-requested count exactly while retaining meaningful names.
        if len(fields)<count:
            for i in range(len(fields)+1,count+1): fields.append(f'{key}_field_{i:02d}')
        else: fields=fields[:count]
        for i,name in enumerate(fields,1):
            out.append({'id':f'osint.{key}.{i:03d}','category':key,'title':title,'field':name,'position':i})
    return out
